"""Explicitly selected semantic validation engines; no automatic fallback."""

from typing import Protocol

from rdflib import RDF, Graph, Literal
from rdflib.namespace import SH, XSD


class ValidationEngine(Protocol):
    name: str

    def validate(self, shapes: Graph, rdf: Graph) -> list[dict[str, str]]: ...


def _simple_shacl_check(shapes: Graph, rdf: Graph) -> list[dict[str, str]]:
    """Implements only the minCount and hasValue predicates generated by this POC.

    This subset MUST NOT be marketed as a general-purpose SHACL validator.
    """
    issues = []
    for shape in shapes.subjects(RDF.type, SH.NodeShape):
        for focus in shapes.objects(shape, SH.targetNode):
            for prop in shapes.objects(shape, SH.property):
                paths = list(shapes.objects(prop, SH.path))
                if not paths:
                    continue
                predicate = paths[0]
                values = list(rdf.objects(focus, predicate))
                if (prop, SH.minCount, Literal(1, datatype=XSD.integer)) in shapes and not values:
                    issues.append(
                        {
                            "path": str(focus),
                            "rule": str(predicate),
                            "message": "Required RDF property is missing.",
                        }
                    )
                expected = list(shapes.objects(prop, SH.hasValue))
                if expected and expected[0] not in values:
                    issues.append(
                        {
                            "path": str(focus),
                            "rule": str(predicate),
                            "message": f"Expected RDF value: {expected[0]}",
                        }
                    )
    return issues


class SubsetEngine:
    name = "POC subset (minCount and hasValue only); install pyshacl for complete SHACL Core"

    def validate(self, shapes, rdf):
        return _simple_shacl_check(shapes, rdf)


class PyShaclEngine:
    name = "pySHACL"

    def __init__(self):
        try:
            from pyshacl import validate
        except ImportError as exc:
            raise RuntimeError(
                "pySHACL is required by the selected engine. Install the backend package (pip install -e ./backend) or explicitly select FAIR_HDF5_SHACL_ENGINE=subset."
            ) from exc
        self._validate = validate

    def validate(self, shapes, rdf):
        conforms, report, _ = self._validate(
            rdf, shacl_graph=shapes, inference="none", abort_on_first=False
        )
        if conforms:
            return []
        return [
            {
                "path": str(next(report.objects(r, SH.focusNode), "")),
                "rule": str(next(report.objects(r, SH.resultPath), "SHACL")),
                "message": str(next(report.objects(r, SH.resultMessage), "SHACL violation")),
            }
            for r in report.subjects(RDF.type, SH.ValidationResult)
        ]


def create_engine(name: str) -> ValidationEngine:
    if name == "pyshacl":
        return PyShaclEngine()
    if name == "subset":
        return SubsetEngine()
    raise ValueError(f"Unknown SHACL engine: {name}")
